package org.pumpkinlib.vision;

public enum PoseSource { MEGATAG_1, MEGATAG_2, MULTI_TAG_COPROC, SINGLE_TAG_PNP,
                         PNP_DISTANCE_TRIG, CONSTRAINED_SOLVEPNP, CUSTOM, SIM }

/** One target seen in one frame. Tag or detected object. */
public record TargetObservation(
    int id,                       // fiducial id, or -1
    int objectClassId,            // detector class, or -1
    double confidence,            // 0..1, NaN if N/A
    Rotation2d tx, Rotation2d ty, // yaw/pitch to target, principal-point relative
    double areaPercent,
    double ambiguity,             // NaN if N/A
    Optional<Transform3d> bestCameraToTarget,
    Optional<Transform3d> altCameraToTarget,
    double[] cornerTx, double[] cornerTy) {}

/** One frame from one camera. Superset of AdvantageKit's PoseObservation. */
public record VisionFrame(
    int cameraIndex,
    double timestampSeconds,      // FPGA seconds at MIDDLE OF EXPOSURE
    Optional<Pose3d> robotPose,   // already transformed to robot frame
    PoseSource source,
    int tagCount,
    double averageTagDistanceMeters,
    double tagSpanMeters,
    double ambiguity,             // 0 for multi-tag / MegaTag2
    int[] tagIds,
    List<TargetObservation> targets) implements StructSerializable {
  public static final Struct<VisionFrame> struct = new VisionFrameStruct();
}
