```java
@FunctionalInterface public interface StdDevModel {
  Matrix<N3,N1> compute(VisionFrame f, VisionContext ctx);

  /** AdvantageKit template: factor = d^2 / n; linear 0.02, angular 0.06 baseline @1m,1tag.
   *  MegaTag2: linear *= 0.5, angular = POSITIVE_INFINITY. */
  static StdDevModel advantageKit(double linearBaseline, double angularBaseline);

  /** FRC 6328 Darwin (2026): xy = 0.01 * d^2 / n^2 * cameraFactor;
   *  theta = 0.03 * d^2 / n^2 * cameraFactor, or POSITIVE_INFINITY when rotation is untrusted. */
  static StdDevModel littletonInverseSquareTagCount(double xyCoeff, double thetaCoeff);

  /** Limelight-documented MegaTag2 baseline: VecBuilder.fill(0.7, 0.7, 9999999). */
  static StdDevModel limelightMegaTag2Default();

  default StdDevModel scaledBy(double perCameraFactor);
  default StdDevModel withAngularDisabled();  // theta -> POSITIVE_INFINITY
}
